mapper.select:
select from biz_project_proposal p left join sys_dept company on company.dept_id=p.company_dept_id and company.del_flag='0' left join biz_project parent on parent.project_id=p.parent_project_id and parent.del_flag='0' where p.del_flag='0' and p.applicant_user_id=#{userId} and p.status=#{status}
and (p.project_name like concat('%',#{keyword},'%') or p.proposal_no like concat('%',#{keyword},'%'))
order by p.update_time desc,p.create_time desc,p.proposal_id desc

mapper.update:
update biz_project_proposal set del_flag='2',update_by=#{userName},update_time=sysdate(),version=version+1
where proposal_id=#{proposalId} and applicant_user_id=#{applicantUserId} and status='DRAFT'
  and del_flag='0' and version=#{version}

update biz_project_proposal set status='PENDING',submission_version=submission_version+1,
  submitted_time=sysdate(),review_comment=null,reviewed_user_id=null,reviewed_user_name=null,reviewed_time=null,
  update_by=#{userName},update_time=sysdate(),version=version+1
where proposal_id=#{proposalId} and applicant_user_id=#{applicantUserId}
  and status in ('DRAFT','RETURNED','WITHDRAWN') and del_flag='0' and version=#{version}

update biz_project_proposal set status='APPROVED',submission_version=submission_version+1,
  submitted_time=sysdate(),reviewed_user_id=#{applicantUserId},reviewed_user_name=#{operatorName},
  reviewed_time=sysdate(),review_comment='负责人自主确认并启动',created_project_id=#{createdProjectId},
  update_by=#{userName},update_time=sysdate(),version=version+1
where proposal_id=#{proposalId} and applicant_user_id=#{applicantUserId}
  and status in ('DRAFT','RETURNED','WITHDRAWN') and del_flag='0' and version=#{version}

update biz_project_proposal set status='WITHDRAWN',review_comment=#{comment},update_by=#{userName},
  update_time=sysdate(),version=version+1
where proposal_id=#{proposalId} and applicant_user_id=#{applicantUserId}
  and status='PENDING' and del_flag='0' and version=#{version}

update biz_project_proposal set status=#{decision},reviewed_user_id=#{reviewedUserId},
  reviewed_user_name=#{reviewedUserName},reviewed_time=sysdate(),review_comment=#{reviewComment},
  created_project_id=#{createdProjectId},update_by=#{userName},update_time=sysdate(),version=version+1
where proposal_id=#{proposalId} and sponsor_owner_user_id=#{sponsorOwnerUserId}
  and status='PENDING' and del_flag='0' and version=#{version}
